solution:
public static int WeightedScore(int[] values, int[] weights)
{
    long sum = 0, total = 0; for (int i = 0; i < values.Length; i++) { sum += (long)values[i] * weights[i]; total += weights[i]; } return total == 0 ? 0 : (int)(sum / total);
}

