public static int[] Rotate(int[] values, int shift)
{
    int n = values.Length; if (n == 0) return []; int k = shift % n; var result = new int[n]; for (int i = 0; i < n; i++) result[(i + k) % n] = values[i]; return result;
}

solution:
public static int[] Rotate(int[] values, int shift)
{
    int n = values.Length; if (n == 0) return []; int k = ((shift % n) + n) % n; var result = new int[n]; for (int i = 0; i < n; i++) result[(i + k) % n] = values[i]; return result;
}

starter:
public static int BestProfit(int[] prices)
{
    if (prices.Length < 2) return 0; int low = prices[0], best = int.MinValue; for (int i = 1; i < prices.Length; i++) { best = Math.Max(best, prices[i] - low); low = Math.Min(low, prices[i]); } return best;
}

solution:
public static int BestProfit(int[] prices)
{
    if (prices.Length == 0) return 0; int low = prices[0], best = 0; foreach (int p in prices) { best = Math.Max(best, p - low); low = Math.Min(low, p); } return best;
}

